import React, { createContext, useContext, useEffect, useMemo, useState } from 'react';
import { HashRouter, Link, NavLink, Navigate, Outlet, Route, Routes, useLocation, useNavigate, useOutletContext } from 'react-router-dom';
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion';
import { ArrowDownWideNarrow, ArrowLeft, ArrowRight, Bell, CalendarDays, Check, CheckCheck, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, Circle, Clock3, Flower2, Grid2X2, Heart, Home, LayoutDashboard, List, LogOut, Menu, MoreHorizontal, Plus, Search, Settings, SlidersHorizontal, Sparkles, Tag, Trash2, Users, X, Eye, EyeOff, Sunrise, Sunset, CloudSun, Leaf, CalendarClock, CircleHelp, LoaderCircle } from 'lucide-react';
